:root{--primary:#1d4ed8;--primary-dark:#1e40af;--text:#172033;--muted:#667085;--border:#e4e7ec;--background:#f5f7fb}*{box-sizing:border-box}body{margin:0;font-family:Arial,Helvetica,sans-serif;background:var(--background);color:var(--text)}button,a{font:inherit}.screen-wrap{width:min(1120px,100%);margin:0 auto;padding:24px 20px 40px}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:14px}.toolbar-group{display:flex;gap:8px;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;min-height:38px;padding:9px 13px;border-radius:8px;border:1px solid transparent;text-decoration:none;cursor:pointer;font-size:13px;font-weight:700}.btn-primary{background:var(--primary);color:#fff}.btn-primary:hover{background:var(--primary-dark)}.btn-secondary{background:#fff;color:#344054;border-color:#d0d5dd}.btn-success{background:#15803d;color:#fff}.doc-nav{display:flex;gap:7px;flex-wrap:wrap;padding:10px;background:#fff;border:1px solid var(--border);border-radius:10px;margin-bottom:16px}.doc-link{padding:7px 10px;border-radius:7px;border:1px solid #d0d5dd;color:#344054;background:#fff;text-decoration:none;font-size:12px;font-weight:800}.doc-link.active{color:#1d4ed8;border-color:#93c5fd;background:#eff6ff}.doc-link.done{color:#166534;border-color:#bbf7d0;background:#f0fdf4}.doc-link.missing{color:#92400e;border-color:#fde68a;background:#fffbeb}.flash{padding:11px 13px;margin-bottom:14px;border:1px solid #bbf7d0;background:#f0fdf4;color:#166534;border-radius:8px;font-size:13px}.paper{width:210mm;min-height:297mm;margin:0 auto;background:#fff;box-shadow:0 5px 22px rgba(16,24,40,.12);padding:16mm 17mm;color:#111}.letterhead{text-align:center;border-bottom:3px double #111;padding-bottom:9px;margin-bottom:18px}.letterhead h1{font-size:18px;margin:0 0 5px;text-transform:uppercase}.letterhead p{font-size:11px;margin:3px 0;line-height:1.35}.doc-title{text-align:center;margin:18px 0 22px}.doc-title h2{font-size:16px;letter-spacing:.7px;text-decoration:underline;margin:0 0 6px}.doc-title p{font-size:12px;margin:0}.meta-table,.detail-table{width:100%;border-collapse:collapse}.meta-table td{padding:3px 0;font-size:12px;vertical-align:top}.meta-table .label{width:130px}.detail-table{margin-top:18px}.detail-table th,.detail-table td{border:1px solid #111;padding:7px 8px;font-size:11px;vertical-align:top}.detail-table th{text-align:center;background:#f6f6f6}.right{text-align:right}.center{text-align:center}.body-copy{font-size:12px;line-height:1.65;text-align:justify}.amount-box{display:inline-block;margin-top:18px;padding:10px 16px;border:1.5px solid #111;font-weight:800;font-size:17px;background:#fafafa}.signature-table{width:100%;border-collapse:collapse;margin-top:42px}.signature-table td{width:50%;text-align:center;vertical-align:top;font-size:11px;line-height:1.45}.signature-space{height:68px}.signature-name{font-weight:800;text-decoration:underline}.receipt-box{border:1.8px solid #111;padding:13mm 12mm;min-height:170mm}.receipt-title{text-align:center;margin-bottom:25px}.receipt-title h1{font-size:22px;text-decoration:underline;letter-spacing:1px;margin:0 0 6px}.receipt-title p{font-size:12px;margin:0}.receipt-table{width:100%;border-collapse:collapse}.receipt-table td{padding:7px 3px;font-size:13px;vertical-align:top}.receipt-table .label{width:145px}.receipt-table .colon{width:18px}.receipt-terbilang{font-style:italic;line-height:1.55}.receipt-signature{width:300px;margin:38px 0 0 auto;text-align:center;font-size:12px}.receipt-signature .space{height:65px}
@media(max-width:900px){.screen-wrap{padding:16px 10px 30px;overflow-x:auto}.paper{transform-origin:top left}.toolbar{align-items:flex-start}}
@media print{@page{size:A4 portrait;margin:0}body{background:#fff}.no-print{display:none!important}.screen-wrap{width:auto;margin:0;padding:0}.paper{width:210mm;min-height:297mm;margin:0;box-shadow:none;padding:16mm 17mm;page-break-after:avoid}.receipt-box{min-height:0}.detail-table{page-break-inside:avoid}.signature-table{page-break-inside:avoid}}
